// 인증된 UI 표시
scwin.showAuthenticatedUI = function () {
    dm_auth_status.set("needsLogin", "false");
    dm_auth_status.set("isAuthenticated", "true");

    try {
        var loginSection = $p.getComponentById("login_required_section");
        if (loginSection) {
            loginSection.hide();
            loginSection.addClass("hidden");
        }

        var mainContent = $p.getComponentById("github_main_content");
        if (mainContent) {
            mainContent.show();
        }
    } catch (e) {
        console.error("UI 업데이트 실패:", e);
    }

    console.log("인증된 사용자 UI 표시");
};

// GitHub 레포지토리 목록 로드 (프론트엔드에서 직접 GitHub API 호출)
scwin.loadConnectedRepositories = function () {
    if (dm_auth_status.get("needsLogin") === "true") {
        console.log("인증되지 않은 상태 - 레포지토리 로드 건너뜀");
        return;
    }

    scwin.setLoading(true, "GitHub 레포지토리 목록 로딩 중...");

    // 레포지토리 로딩 상태 표시
    scwin.showRepositoryLoadingState();

    // 먼저 세션에서 GitHub 토큰 가져오기
    $.ajax({
        url: "/InsWebApp/github/auth/status.pwkjson",
        type: "GET",
        dataType: "json",
        success: function (authResult) {
            if (!authResult.authenticated) {
                scwin.setLoading(false);
                scwin.showLoginRequiredUI();
                return;
            }

            // GitHub API 직접 호출 (CORS 문제로 프록시 방식 사용)
            $.ajax({
                url: "/InsWebApp/github/api/repositories.pwkjson",
                type: "GET",
                dataType: "json",
                data: {
                    sort: "updated",
                    per_page: 100,
                    affiliation: "owner,collaborator"
                },
                success: function (repositories) {
                    scwin.setLoading(false);
                    console.log("GitHub 레포지토리 목록 로드 완료:", repositories);
                    console.log("데이터 타입:", typeof repositories);

                    // DataList 초기화
                    dlt_GitHubRepositoryVoList.removeAll();

                    // 문자열을 JSON으로 파싱
                    try {
                        if (typeof repositories === 'string') {
                            repositories = JSON.parse(repositories);
                            console.log("JSON 파싱 완료:", repositories);
                        }
                    } catch (e) {
                        console.error("JSON 파싱 실패:", e);
                        scwin.showEmptyRepositoryState();
                        return;
                    }

                    // 레포지토리 데이터 검증
                    if (!Array.isArray(repositories)) {
                        console.error("저장소 데이터가 배열이 아닙니다:", repositories);
                        scwin.showEmptyRepositoryState();
                        return;
                    }

                    // 첫 번째 저장소 구조 확인
                    if (repositories.length > 0) {
                        console.log("첫 번째 저장소 구조:", {
                            name: repositories[0].name,
                            owner: repositories[0].owner,
                            private: repositories[0].private,
                            html_url: repositories[0].html_url
                        });
                    }

                    // 레포지토리 데이터를 직접 카드 형태로 출력
                    console.log("GitHub 저장소 목록 (파싱 후):", repositories);
                    scwin.renderRepositoryCards(repositories);

                    // 레포지토리 개수 표시 업데이트
                    scwin.updateRepositoryCount(repositories.length);
                },
                error: function (xhr, status, error) {
                    scwin.setLoading(false);
                    console.error("GitHub API 요청 실패:", {
                        status: xhr.status,
                        statusText: xhr.statusText,
                        responseText: xhr.responseText,
                        error: error
                    });

                    scwin.showEmptyRepositoryState();

                    if (xhr.status === 401) {
                        $c.win.alert("GitHub 인증이 만료되었습니다. 다시 로그인해주세요.");
                        scwin.showLoginRequiredUI();
                    } else {
                        $c.win.alert("GitHub에서 레포지토리 목록을 불러올 수 없습니다.\n오류: " + (xhr.responseText || error));
                    }
                }
            });
        },
        error: function (xhr, status, error) {
            scwin.setLoading(false);
            console.error("인증 상태 확인 실패:", error);
            scwin.showLoginRequiredUI();
        }
    });
};

// 레포지토리 표시 업데이트
scwin.updateRepositoryDisplay = function () {
    try {
        var totalRepos = dlt_GitHubRepositoryVoList.getTotalRow();
        var privateRepos = 0;
        var publicRepos = 0;

        // 상태 카운트 계산
        for (var i = 0; i < totalRepos; i++) {
            var isPrivate = dlt_GitHubRepositoryVoList.getCellData(i, "isPrivate");
            if (isPrivate && isPrivate.indexOf("Private") !== -1) {
                privateRepos++;
            } else {
                publicRepos++;
            }
        }

        // 헤더 정보 업데이트
        var countText = "총 " + totalRepos + "개 레포지토리 (" +
            publicRepos + "개 공개, " + privateRepos + "개 비공개)";

        var countElement = document.getElementById("repo-count-info");
        if (countElement) {
            countElement.textContent = countText;
        }

        // 카드 형태로 레포지토리 표시
        scwin.renderRepositoryCards();

        console.log("레포지토리 표시 업데이트:", countText);
    } catch (e) {
        console.error("레포지토리 표시 업데이트 실패:", e);
    }
};

// 레포지토리 카드 렌더링 (웹스퀘어 방식)
scwin.renderRepositoryCards = function (repositories) {
    try {
        // 카드 컨테이너 찾기
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (!cardsContainer) {
            console.error("카드 컨테이너를 찾을 수 없습니다.");
            return;
        }

        // 컨테이너 스크롤 스타일 적용 (웹스퀘어 방식)
        try {
            var containerComponent = $p.getComponentById("repo_cards_container");
            if (containerComponent) {
                // JavaScript 방식으로 스타일 적용
                var realDomElement = document.getElementById(containerComponent.id);
                if (realDomElement) {
                    console.log("=== DOM 요소 스타일 분석 (수정 전) ===");
                    console.log("인라인 스타일:", realDomElement.style.cssText);
                    console.log("클래스 목록:", realDomElement.classList.toString());
                    console.log("계산된 display:", window.getComputedStyle(realDomElement).display);

                    // 강제로 display: grid 적용
                    realDomElement.style.display = "grid";
                    realDomElement.style.maxHeight = "350px";
                    realDomElement.style.overflowY = "auto";
                    realDomElement.style.padding = "10px";
                    realDomElement.style.visibility = "visible";

                    console.log("=== DOM 요소 스타일 분석 (수정 후) ===");
                    console.log("인라인 스타일:", realDomElement.style.cssText);
                    console.log("계산된 display:", window.getComputedStyle(realDomElement).display);
                    console.log("계산된 max-height:", window.getComputedStyle(realDomElement).maxHeight);
                    console.log("계산된 overflow-y:", window.getComputedStyle(realDomElement).overflowY);

                    // 비동기 스타일 재적용 함수
                    const recheckAndApplyStyles = async () => {
                        // 웹스퀘어 렌더링 완료 대기
                        await new Promise(resolve => setTimeout(resolve, 100));

                        console.log("=== 지연 후 재확인 ===");
                        console.log("지연 후 인라인 스타일:", realDomElement.style.cssText);
                        console.log("지연 후 계산된 display:", window.getComputedStyle(realDomElement).display);

                        // 웹스퀘어가 덮어썼다면 다시 적용
                        if (realDomElement.style.display !== "grid") {
                            console.log("웹스퀘어가 스타일을 덮어썼습니다. 다시 적용합니다.");
                            realDomElement.style.display = "grid";
                            realDomElement.style.setProperty("display", "grid", "important");
                            console.log("!important로 강제 적용 완료");

                            // 추가 확인 (한 번 더 대기 후 최종 확인)
                            await new Promise(resolve => setTimeout(resolve, 50));
                            console.log("최종 확인 - 인라인 스타일:", realDomElement.style.cssText);
                        } else {
                            console.log("웹스퀘어 스타일이 유지되고 있습니다.");
                        }
                    };

                    // 비동기 함수 실행
                    recheckAndApplyStyles().catch(console.error);
                } else {
                    console.log("실제 DOM 요소를 찾을 수 없습니다.");
                }
            } else {
                console.log("WebSquare 컨테이너를 찾을 수 없습니다.");
            }
        } catch (e) {
            console.log("WebSquare 스타일 적용 실패:", e);
        }

        // 로딩 상태 숨기기
        var loadingSection = $p.getComponentById("repo_loading_section");
        if (loadingSection) {
            loadingSection.hide();
        }

        if (!repositories || repositories.length === 0) {
            // 빈 상태 표시
            var emptySection = $p.getComponentById("repo_empty_section");
            if (emptySection) {
                emptySection.show();
            }
            cardsContainer.hide();
            return;
        }

        // 빈 상태 숨기기
        var emptySection = $p.getComponentById("repo_empty_section");
        if (emptySection) {
            emptySection.hide();
        }

        // 기존 카드 제거
        scwin.clearRepositoryCards();

        // 각 레포지토리를 카드로 렌더링
        for (var i = 0; i < repositories.length; i++) {
            var repo = repositories[i];
            scwin.createRepositoryCard(repo, i, cardsContainer);
        }

        // 카드 컨테이너 표시
        cardsContainer.show();

        console.log("레포지토리 카드 렌더링 완료:", repositories.length + "개");
    } catch (e) {
        console.error("레포지토리 카드 렌더링 실패:", e);
    }
};

// 저장소 개수 업데이트
scwin.updateRepositoryCount = function (count) {
    try {
        var countElement = document.getElementById("repo-count-info");
        if (countElement) {
            countElement.textContent = "총 " + count + "개의 저장소";
        }
    } catch (e) {
        console.error("저장소 개수 업데이트 실패:", e);
    }
};

// 날짜 포맷팅 함수
scwin.formatDate = function (dateString) {
    try {
        if (!dateString) return "";
        var date = new Date(dateString);
        return date.toLocaleDateString('ko-KR');
    } catch (e) {
        return dateString;
    }
};

// 기존 카드 제거
scwin.clearRepositoryCards = function () {
    try {
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (cardsContainer) {
            // 자식 컴포넌트들을 모두 제거
            var children = cardsContainer.getChildren();
            for (var i = children.length - 1; i >= 0; i--) {
                children[i].remove();
            }
        }
    } catch (e) {
        console.error("카드 제거 실패:", e);
    }
};

// 저장소 카드 생성 (웹스퀘어 방식)
scwin.createRepositoryCard = function (repo, index, container) {
    try {
        var cardId = "repo_card_" + index;
        var isPrivate = repo.private || false;
        var visibilityText = isPrivate ? "������ Private" : "������ Public";
        var visibilityClass = isPrivate ? "private" : "public";
        var language = repo.language || "Unknown";
        var stars = repo.stargazers_count || 0;
        var forks = repo.forks_count || 0;
        var description = repo.description || "설명이 없습니다.";
        var updatedAt = scwin.formatDate(repo.updated_at) || "업데이트 정보 없음";

        // 카드 그룹 생성
        var cardGroup = $p.dynamicCreate(
            cardId,
            "group",
            {
                style: "background: white; border: 1px solid #e9ecef; border-radius: 12px; padding: 20px; margin-bottom: 16px; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1); transition: all 0.2s ease; cursor: pointer; display: block;",
                className: "repo-card"
            },
            container
        );

        // 카드 헤더 그룹
        var headerGroup = $p.dynamicCreate(
            cardId + "_header",
            "group",
            {
                style: "display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px;",
                className: "repo-card-header"
            },
            cardGroup
        );

        // 왼쪽 정보 그룹
        var leftInfoGroup = $p.dynamicCreate(
            cardId + "_left_info",
            "group",
            {
                style: "flex: 1;",
                className: "repo-left-info"
            },
            headerGroup
        );

        // 소유자 이름
        var ownerSpan = $p.dynamicCreate(
            cardId + "_owner",
            "span",
            {
                style: "font-size: 14px; color: #6c757d; margin-bottom: 4px; display: block;",
                className: "repo-owner"
            },
            leftInfoGroup
        );
        ownerSpan.setValue(repo.owner ? repo.owner.login : "");

        // 저장소 이름
        var nameSpan = $p.dynamicCreate(
            cardId + "_name",
            "span",
            {
                style: "font-size: 18px; font-weight: 600; color: #2c3e50; margin: 0; line-height: 1.3; display: block;",
                className: "repo-name"
            },
            leftInfoGroup
        );
        nameSpan.setValue(repo.name || "");

        // 가시성 표시
        var visibilitySpan = $p.dynamicCreate(
            cardId + "_visibility",
            "span",
            {
                style: "display: inline-flex; align-items: center; padding: 4px 8px; border-radius: 12px; font-size: 12px; font-weight: 500; " +
                    (isPrivate ? "background-color: #fff3cd; color: #856404;" : "background-color: #d4edda; color: #155724;"),
                className: "repo-visibility " + visibilityClass
            },
            headerGroup
        );
        visibilitySpan.setValue(visibilityText);

        // 설명
        var descSpan = $p.dynamicCreate(
            cardId + "_desc",
            "span",
            {
