        });

        // 카드 클릭 이벤트 (카드 선택 효과)
        cardGroup.bind("onclick", function () {
            scwin.highlightSelectedCard(cardId);
        });

        console.log("카드 생성 완료:", repo.name);
    } catch (e) {
        console.error("카드 생성 실패:", e);
    }
};

// 선택된 카드 하이라이트
scwin.highlightSelectedCard = function (selectedCardId) {
    try {
        var container = $p.getComponentById("repo_cards_container");
        if (container) {
            var children = container.getChildren();
            for (var i = 0; i < children.length; i++) {
                var card = children[i];
                var cardId = card.id || card.getId();
                if (cardId === selectedCardId) {
                    // 선택된 카드 스타일
                    card.setStyle("border-color", "#007bff");
                    card.setStyle("box-shadow", "0 4px 16px rgba(0, 123, 255, 0.15)");
                } else {
                    // 일반 카드 스타일
                    card.setStyle("border-color", "#e9ecef");
                    card.setStyle("box-shadow", "0 2px 8px rgba(0, 0, 0, 0.1)");
                }
            }
        }
    } catch (e) {
        console.error("카드 하이라이트 실패:", e);
    }
};

// 저장소 선택 처리
scwin.selectRepository = function (repoId, repoName, repoOwner, repoData) {
    try {
        console.log('=== 저장소 선택 함수 호출됨 ===');
        console.log('repoId:', repoId);
        console.log('repoName:', repoName);
        console.log('repoOwner:', repoOwner);
        console.log('repoData:', repoData);
        console.log('저장소 선택:', repoOwner + '/' + repoName);

        // 현재 프로젝트에 이미 연결된 저장소가 있는지 확인
        if (scwin.currentRepository) {
            var currentRepo = scwin.currentRepository.owner + "/" + scwin.currentRepository.name;
            var selectedRepo = repoOwner + "/" + repoName;

            if (currentRepo === selectedRepo) {
                $c.win.alert("이미 연결된 저장소입니다.");
                return;
            }

            // 다른 저장소가 이미 연결되어 있는 경우 교체 확인
            var confirmMessage = "현재 프로젝트에 다른 저장소가 연결되어 있습니다.\n";
            confirmMessage += "현재 연결된 저장소: " + currentRepo + "\n";
            confirmMessage += "새로 선택한 저장소: " + selectedRepo + "\n\n";
            confirmMessage += "저장소를 교체하시겠습니까?";

            if (!confirm(confirmMessage)) {
                console.log('사용자가 저장소 교체를 취소했습니다.');
                return;
            }
        }

        // 선택된 저장소 정보 설정
        dm_ui_state.set("selectedRepo", repoOwner + "/" + repoName);

        // 현재 선택된 저장소 정보를 저장해서 콜백에서 사용
        scwin.currentSelectingRepo = {
            id: repoId,
            name: repoName,
            owner: repoOwner,
            data: repoData
        };

        // DataMap에 개별 필드로 설정 (새로운 프로젝트 ID 헬퍼 함수 사용)
        var projectId = scwin.getCurrentProjectId();
        dm_repository_select.set("projectId", projectId);
        dm_repository_select.set("githubRepositoryId", repoId ? repoId.toString() : "");
        dm_repository_select.set("repoOwner", repoOwner || "");
        dm_repository_select.set("repoName", repoName || "");
        dm_repository_select.set("defaultBranch", repoData.default_branch || "main");
        dm_repository_select.set("githubAppInstallationId", "");

        console.log('DataMap 설정 완료:', {
            projectId: dm_repository_select.get("projectId"),
            githubRepositoryId: dm_repository_select.get("githubRepositoryId"),
            repoOwner: dm_repository_select.get("repoOwner"),
            repoName: dm_repository_select.get("repoName"),
            defaultBranch: dm_repository_select.get("defaultBranch"),
            githubAppInstallationId: dm_repository_select.get("githubAppInstallationId")
        });

        // 서브미션 실행
        console.log('서브미션 실행 전');
        $p.executeSubmission("sbm_connectRepository");
        console.log('서브미션 실행 후');

    } catch (e) {
        console.error("저장소 선택 처리 실패:", e);
        $c.win.alert("저장소 선택 중 오류가 발생했습니다: " + e.message);
    }
};

// 저장소 연결 성공 콜백
scwin.sbm_connectRepository_submitdone = function (e) {
    console.log('저장소 연결 성공:', e);

    try {
        var response = e.responseJSON || e.response;

        if (response && response.success) {
            var repoInfo = scwin.currentSelectingRepo;
            $c.win.alert("저장소가 성공적으로 프로젝트에 연결되었습니다:\n" + repoInfo.owner + "/" + repoInfo.name);

            // 브랜치 관리 화면으로 전환
            scwin.showBranchManagement(repoInfo);

        } else {
            $c.win.alert("저장소 연결 실패:\n" + (response.error || "알 수 없는 오류"));
        }
    } catch (err) {
        console.error("저장소 연결 응답 처리 실패:", err);
        $c.win.alert("저장소 연결 응답 처리 중 오류가 발생했습니다.");
    }

    // 임시 데이터 정리
    scwin.currentSelectingRepo = null;
};

// 저장소 연결 실패 콜백
scwin.sbm_connectRepository_submiterror = function (e) {
    console.error('저장소 연결 실패:', e);

    try {
        var errorMsg = "저장소 연결 중 오류가 발생했습니다.";

        if (e.responseText) {
            errorMsg += "\n오류 내용: " + e.responseText;
        } else if (e.statusText) {
            errorMsg += "\n오류 상태: " + e.statusText;
        }

        $c.win.alert(errorMsg);
    } catch (err) {
        console.error("에러 처리 중 오류:", err);
        $c.win.alert("저장소 연결 중 오류가 발생했습니다.");
    }

    // 임시 데이터 정리
    scwin.currentSelectingRepo = null;
};

// 레포지토리 카드 HTML 생성
scwin.createRepositoryCardHtml = function (repo) {
    var isPrivate = repo.isPrivate;
    var visibilityClass = isPrivate ? "private" : "public";
    var visibilityText = isPrivate ? "������ Private" : "������ Public";
    var language = repo.language || "Unknown";
    var stars = parseInt(repo.stars) || 0;
    var forks = parseInt(repo.forks) || 0;
    var description = repo.description || "설명이 없습니다.";
    var updatedAt = repo.updatedAt || "업데이트 정보 없음";

    return `
        <div class="repo-card" data-repo-id="${repo.id}" data-repo-name="${repo.name}" data-repo-owner="${repo.owner}">
            <div class="repo-card-header">
                <div>
                    <div class="repo-owner">${repo.owner}</div>
                    <h3 class="repo-name">${repo.name}</h3>
                <span class="repo-visibility ${visibilityClass}">${visibilityText}</span>
            </div>

            <div class="repo-description">${description}</div>

            <div class="repo-stats">
                <div class="repo-stat">
                    <svg class="repo-stat-icon" viewBox="0 0 16 16" fill="currentColor">
                        <path d="M8 .25a.75.75 0 01.673.418l1.882 3.815 4.21.612a.75.75 0 01.416 1.279l-3.046 2.97.719 4.192a.75.75 0 01-1.088.791L8 12.347l-3.766 1.98a.75.75 0 01-1.088-.79l.72-4.194L.818 6.374a.75.75 0 01.416-1.28l4.21-.611L7.327.668A.75.75 0 018 .25zm0 2.445L6.615 5.5a.75.75 0 01-.564.41l-3.097.45 2.24 2.184a.75.75 0 01.216.664l-.528 3.084 2.769-1.456a.75.75 0 01.698 0l2.77 1.456-.53-3.084a.75.75 0 01.216-.664l2.24-2.183-3.096-.45a.75.75 0 01-.564-.41L8 2.694v.001z"/>
                    </svg>
                    ${stars}
                </div>
                <div class="repo-stat">
                    <svg class="repo-stat-icon" viewBox="0 0 16 16" fill="currentColor">
                        <path d="M5 3.25a.75.75 0 11-1.5 0 .75.75 0 011.5 0zm0 2.122a2.25 2.25 0 10-1.5 0v.878A2.25 2.25 0 005.75 8.5h1.5v2.128a2.251 2.251 0 101.5 0V8.5h1.5a2.25 2.25 0 002.25-2.25v-.878a2.25 2.25 0 10-1.5 0v.878a.75.75 0 01-.75.75h-4.5A.75.75 0 015 6.25v-.878z"/>
                    </svg>
                    ${forks}
                </div>
                <div class="repo-language">
                    <span class="language-dot"></span>
                    ${language}
                </div>
            </div>

            <div class="repo-footer">
                <div class="repo-updated">업데이트: ${updatedAt}</div>
                <div class="repo-actions">
                    <button class="repo-action-btn primary" onclick="scwin.selectRepository('${repo.id}', '${repo.name}', '${repo.owner}')">
                        선택
                    </button>
                    <button class="repo-action-btn" onclick="window.open('${repo.url}', '_blank')">
                        GitHub
                    </button>
                </div>
            </div>
        </div>
    `;
};

// 카드 이벤트 연결
scwin.attachCardEvents = function () {
    try {
        var cards = document.querySelectorAll('.repo-card');
        cards.forEach(function (card) {
            card.addEventListener('click', function (e) {
                // 버튼 클릭 시에는 카드 선택 이벤트 방지
                if (e.target.classList.contains('repo-action-btn')) {
                    return;
                }

                var repoId = card.dataset.repoId;
                var repoName = card.dataset.repoName;
                var repoOwner = card.dataset.repoOwner;

                // 기존 선택된 카드 스타일 제거
                document.querySelectorAll('.repo-card').forEach(function (c) {
                    c.style.borderColor = '#e9ecef';
                });

                // 현재 카드를 선택된 상태로 표시
                card.style.borderColor = '#007bff';

                console.log('저장소 카드 선택:', repoOwner + '/' + repoName);

                // 선택된 저장소 정보 설정
                dm_ui_state.set("selectedRepo", repoOwner + "/" + repoName);
            });
        });
    } catch (e) {
        console.error("카드 이벤트 연결 실패:", e);
    }
};

