// ==============================

// 브랜치 관리 화면 표시 (통합 함수)
scwin.showBranchManagement = function (repoInfo) {
    try {
        console.log('브랜치 관리 화면 표시:', repoInfo);

        // 저장소 정보 정규화 (데이터베이스 VO와 선택된 저장소 데이터 통일)
        var normalizedRepoInfo = scwin.normalizeRepositoryInfo(repoInfo);

        // 저장소 목록 숨기기
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (cardsContainer) {
            cardsContainer.hide();
        }

        // 브랜치 관리 섹션 표시
        scwin.showBranchManagementSection(normalizedRepoInfo);

        // 브랜치 목록 로드
        scwin.loadBranches(normalizedRepoInfo);

    } catch (e) {
        console.error("브랜치 관리 화면 표시 실패:", e);
    }
};

// 저장소 정보 정규화 (DB VO와 선택된 저장소 데이터 통일)
scwin.normalizeRepositoryInfo = function (repoInfo) {
    try {
        var normalized = {};

        // 데이터베이스 VO 형식인지 확인
        if (repoInfo.repoOwner && repoInfo.repoName) {
            // 데이터베이스 VO 형식
            normalized.owner = repoInfo.repoOwner;
            normalized.name = repoInfo.repoName;
            normalized.default_branch = repoInfo.defaultBranch || "main";
            normalized.projectRepoId = repoInfo.projectRepoId;
            normalized.githubRepositoryId = repoInfo.githubRepositoryId;
        } else {
            // 선택된 저장소 데이터 형식
            normalized.owner = repoInfo.owner;
            normalized.name = repoInfo.name;
            normalized.default_branch = repoInfo.default_branch || "main";
            normalized.projectRepoId = repoInfo.projectRepoId;
            normalized.githubRepositoryId = repoInfo.githubRepositoryId;
        }

        console.log("정규화된 저장소 정보:", normalized);
        return normalized;

    } catch (e) {
        console.error("저장소 정보 정규화 실패:", e);
        return repoInfo; // 실패시 원본 반환
    }
};

