// 브랜치 로딩 상태 표시
scwin.showBranchLoadingState = function () {
    try {
        var container = $p.getComponentById("branch_list_container");
        if (container) {
            // 기존 내용 제거
            var children = container.getChildren();
            for (var i = children.length - 1; i >= 0; i--) {
                children[i].remove();
            }

            // 로딩 메시지 표시
            var loadingSpan = $p.dynamicCreate(
                "branch_loading",
                "span",
                {
                    style: "text-align: center; color: #6c757d; font-size: 16px; padding: 40px;",
                    className: "branch-loading"
                },
                container
            );
            loadingSpan.setValue("브랜치 목록을 불러오는 중...");
        }
    } catch (e) {
        console.error("브랜치 로딩 상태 표시 실패:", e);
    }
};

// 브랜치 에러 상태 표시
scwin.showBranchErrorState = function (message) {
    try {
        var container = $p.getComponentById("branch_list_container");
        if (container) {
            // 기존 내용 제거
            var children = container.getChildren();
            for (var i = children.length - 1; i >= 0; i--) {
                children[i].remove();
            }

            // 에러 메시지 표시
            var errorSpan = $p.dynamicCreate(
                "branch_error",
                "span",
                {
                    style: "text-align: center; color: #dc3545; font-size: 16px; padding: 40px;",
                    className: "branch-error"
                },
                container
            );
            errorSpan.setValue(message || "브랜치 정보를 불러올 수 없습니다.");
        }
    } catch (e) {
        console.error("브랜치 에러 상태 표시 실패:", e);
    }
};

