// 브랜치 목록 조회 성공 콜백
scwin.sbm_loadBranches_submitdone = function (e) {
    console.log('브랜치 목록 조회 성공:', e);

    try {
        var response = e.responseJSON || e.response;

        // 401 인증 오류 체크 (백엔드에서 error_code가 AUTH_EXPIRED로 오는 경우)
        if (response && response.error_code === "AUTH_EXPIRED") {
            console.warn('GitHub 토큰 만료 감지 - 재인증 필요:', response.error);

            // 인증 만료 알림 및 재인증 유도
            $c.win.confirm("GitHub 토큰이 만료되었습니다.\n다시 로그인하시겠습니까?", 
                function(result) {
                    if (result) {
                        // 로그인 페이지로 이동
                        scwin.redirectToGitHubLogin();
                    } else {
                        // 로그인 필요 화면 표시
                        scwin.showLoginRequiredUI();
                    }
                }
            );
            return;
        }

        if (response && response.success) {
            var branches = response.data || [];

            // data가 문자열이면 JSON 파싱
            if (typeof branches === 'string') {
                try {
                    branches = JSON.parse(branches);
                } catch (parseError) {
                    console.error('브랜치 데이터 파싱 실패:', parseError);
                    branches = [];
                }
            }

            console.log('브랜치 목록:', branches);

            // 브랜치 목록 화면에 표시
            scwin.renderBranchList(branches);

        } else {
            console.error('브랜치 목록 조회 실패:', response.error);
            scwin.showBranchErrorState(response.error || "브랜치 목록을 불러올 수 없습니다.");
        }
    } catch (err) {
        console.error("브랜치 목록 조회 응답 처리 실패:", err);
        scwin.showBranchErrorState("브랜치 목록 처리 중 오류가 발생했습니다.");
    }
};

