// 현재 저장소 조회 성공 콜백
scwin.sbm_getCurrentRepository_submitdone = function (e) {
    console.log('현재 저장소 조회 성공:', e);

    try {
        var response = e.responseJSON || e.response;

        if (response && response.success && response.repository) {
            var repository = response.repository;
            console.log('✅ 연결된 저장소 발견! 브랜치 관리 화면으로 이동합니다.');
            console.log('저장소 정보:', repository);

            // 저장소 정보를 repoInfo 형태로 변환
            var repoInfo = {
                id: repository.githubRepositoryId,
                name: repository.repoName,
                owner: repository.repoOwner,
                default_branch: repository.defaultBranch || "main"
            };

            // 디버그 로그
            console.log("변환된 repoInfo:", repoInfo);
            console.log("repoInfo.owner:", repoInfo.owner);
            console.log("repoInfo.name:", repoInfo.name);

            // 바로 브랜치 관리 화면으로 이동
            console.log('������ 브랜치 관리 화면으로 자동 이동 시작');
            scwin.showBranchManagementView(repoInfo);

        } else {
            console.log('⚠️ 연결된 저장소가 없습니다. 저장소 목록을 표시합니다.');
            console.log('응답 데이터:', response);
            // 연결된 저장소가 없으면 저장소 선택 화면 표시
            scwin.showRepositorySelectionView();
        }
    } catch (err) {
        console.error("현재 저장소 조회 응답 처리 실패:", err);
        // 오류 발생 시 저장소 선택 화면 표시
        scwin.showRepositorySelectionView();
    }
};

