// 브랜치 삭제 성공 콜백
scwin.sbm_deleteBranch_submitdone = function (e) {
    console.log('브랜치 삭제 성공:', e);

    try {
        var response = e.responseJSON || e.response;
        console.log('브랜치 삭제 응답:', response);

        if (response && response.success) {
            $c.win.alert("✅ 브랜치 삭제 성공!");

            // 브랜치 목록 새로고침
            setTimeout(function() {
                scwin.loadBranches();
            }, 1000);

        } else if (response && response.error_code === 'AUTH_EXPIRED') {
            // 토큰 만료 처리
            console.warn('GitHub 토큰 만료 감지');
            $c.win.confirm("GitHub 토큰이 만료되었습니다. 다시 로그인하시겠습니까?", function(result) {
                if (result) {
                    scwin.redirectToGitHubLogin();
                }
            });
        } else {
            $c.win.alert("❌ 브랜치 삭제 실패\n\n오류: " + (response?.error || "알 수 없는 오류"));
        }
    } catch (err) {
        console.error("브랜치 삭제 응답 처리 실패:", err);
        $c.win.alert("❌ 브랜치 삭제 응답 처리 중 오류가 발생했습니다: " + err.message);
    }
};

// 브랜치 삭제 실패 콜백
scwin.sbm_deleteBranch_submiterror = function (e) {
    console.error('브랜치 삭제 실패:', e);

    var errorMsg = "브랜치 삭제에 실패했습니다.";
    if (e.responseJSON && e.responseJSON.error) {
        errorMsg += "\n\n오류: " + e.responseJSON.error;
    } else if (e.responseText) {
        try {
            var parsed = JSON.parse(e.responseText);
            if (parsed.error) {
                errorMsg += "\n\n오류: " + parsed.error;
            }
        } catch (parseErr) {
            errorMsg += "\n\n원본 오류: " + e.responseText;
        }
    }

    $c.win.alert("❌ " + errorMsg);
};

