// 기타 필요한 함수들
scwin.onRepositorySelect = function () {
    try {
        var selectedRow = dlt_connected_repositories.getFocusedRow();
        if (selectedRow >= 0) {
            var repoId = dlt_connected_repositories.getCellData(selectedRow, "projectRepoId");
            var repoName = dlt_connected_repositories.getCellData(selectedRow, "repoName");
            var repoOwner = dlt_connected_repositories.getCellData(selectedRow, "repoOwner");

            console.log("레포지토리 선택됨:", repoOwner + "/" + repoName);

            // 선택된 레포지토리 정보 설정
            dm_github_form.set("selectedProjectRepoId", repoId);
            dm_github_form.set("currentRepo", repoOwner + "/" + repoName);

            // 브랜치 목록 로드
            var repoInfo = {
                owner: repoOwner,
                name: repoName
            };
            scwin.loadBranches(repoInfo);

            // 웹훅 상태 확인
            scwin.checkWebhookStatus(repoOwner, repoName);
        }
    } catch (e) {
        console.error("레포지토리 선택 처리 실패:", e);
    }
};

scwin.filterRepositories = function (keyword) {
    try {
        console.log("레포지토리 필터링:", keyword);

        if (!keyword || keyword.trim() === "") {
            // 필터 초기화 - 모든 행 표시
            for (var i = 0; i < dlt_connected_repositories.getTotalRow(); i++) {
                dlt_connected_repositories.setRowVisible(i, true);
            }
            return;
        }

        keyword = keyword.toLowerCase();
        var visibleCount = 0;

        for (var i = 0; i < dlt_connected_repositories.getTotalRow(); i++) {
            var repoName = dlt_connected_repositories.getCellData(i, "repoName") || "";
            var repoOwner = dlt_connected_repositories.getCellData(i, "repoOwner") || "";

            var isMatch = repoName.toLowerCase().includes(keyword) ||
                repoOwner.toLowerCase().includes(keyword);

            dlt_connected_repositories.setRowVisible(i, isMatch);
            if (isMatch) visibleCount++;
        }

        console.log("필터링 결과:", visibleCount + "개 레포지토리 표시");
    } catch (e) {
        console.error("레포지토리 필터링 실패:", e);
    }
};

// 브랜치 목록 로드 (대체 구현) - 중복 함수 제거됨
scwin.loadBranchesAlternative = function (owner, repo) {
    console.log("브랜치 목록 로드 (대체):", owner + "/" + repo);

    // 기존 함수 호출 방식으로 변경
    var repoInfo = {
        owner: owner,
        name: repo
    };

    // 첫 번째 함수 호출
    scwin.loadBranches(repoInfo);
};

// 웹훅 상태 확인
scwin.checkWebhookStatus = function (owner, repo) {
    console.log("웹훅 상태 확인:", owner + "/" + repo);

    var requestData = {
        owner: owner,
        repo: repo
    };

    try {
        $c.sbm.execute(sbm_checkWebhookStatus, requestData).then(function (e) {
            console.log("웹훅 상태 확인 완료:", e);
            var result = e.responseJSON || e;
            scwin.updateWebhookStatus(result);
        }).catch(function (e) {
            console.error("웹훅 상태 확인 실패:", e);
            scwin.updateWebhookStatus({ exists: false, error: scwin.getErrorMessage(e) });
        });
    } catch (e) {
        console.error("웹훅 상태 확인 오류:", e);
    }
};

