// GitHub 연결 테스트 (서브미션 방식)
scwin.testGitHubConnection = function () {
    console.log("GitHub 연결 테스트 시작 (서브미션 방식)");

    try {
        // 웹스퀘어 서브미션 실행
        $c.sbm.execute(sbm_testGitHubConnection);
    } catch (e) {
        console.error("서브미션 실행 오류:", e);
        $c.win.alert("❌ 서브미션 실행 중 오류 발생\n\n" + e.message);
    }
};

// GitHub 연결 테스트 완료 핸들러
