// 현재 프로젝트에 연결된 저장소 확인 (프로젝트 ID 기반)
scwin.checkCurrentRepository = function () {
    console.log("=== 현재 프로젝트에 연결된 저장소 확인 ===");

    try {
        // 현재 프로젝트 ID 가져오기
        var projectId = scwin.getCurrentProjectId();
        console.log("현재 프로젝트 ID:", projectId);

        if (!projectId) {
            console.log("프로젝트 ID가 없으므로 저장소 목록 표시");
            scwin.loadGitHubRepositories();
            return;
        }

        // 프로젝트의 연결된 저장소 조회
        $.ajax({
            url: "/InsWebApp/github/project/currentRepository.pwkjson",
            type: "GET",
            dataType: "json",
            data: {
                projectId: projectId
            },
            success: function (result) {
                console.log("현재 프로젝트 저장소 조회 결과:", result);

                if (result && result.success) {
                    if (result.hasRepository && result.repository) {
                        console.log("기존 연결된 저장소 발견:", result.repository.repoOwner + "/" + result.repository.repoName);

                        // 저장소 정보를 전역변수에 저장
                        scwin.connectedRepository = result.repository;

                        // 바로 브랜치 관리 화면으로 이동
                        scwin.showBranchManagement(result.repository);
                    } else {
                        console.log("연결된 저장소가 없음 - 저장소 목록 표시");
                        scwin.loadGitHubRepositories();
                    }
                } else {
                    console.error("저장소 조회 실패:", result.error);
                    scwin.loadGitHubRepositories();
                }
            },
            error: function (xhr, status, error) {
                console.error("현재 프로젝트 저장소 조회 실패:", error);
                scwin.loadGitHubRepositories();
            }
        });

    } catch (e) {
        console.error("현재 프로젝트 저장소 확인 중 오류:", e);
        scwin.loadGitHubRepositories();
    }
};

// 현재 프로젝트 ID 가져오기 헬퍼 함수
scwin.getCurrentProjectId = function () {
    try {
        // 여러 방법으로 프로젝트 ID 찾기
        var projectId = null;

        // 1. WebSquare 파라미터에서 찾기
        try {
            projectId = $p.getParameter("projectId") || $p.getParameter("project_id");
        } catch (e) { }

        // 2. 현재 프로젝트 데이터에서 찾기
        if (!projectId && scwin.currentProjectData) {
            projectId = scwin.currentProjectData.projectId;
        }

        // 3. 데이터맵에서 찾기
        if (!projectId) {
            try {
                projectId = dm_github_form.get("projectId");
            } catch (e) { }
        }

        // 4. URL 파라미터에서 찾기
        if (!projectId) {
            try {
                var urlParams = new URLSearchParams(window.location.search);
                projectId = urlParams.get("projectId") || urlParams.get("project_id");
            } catch (e) { }
        }

        // 5. 세션 스토리지에서 찾기
        if (!projectId && typeof sessionStorage !== 'undefined') {
            try {
                projectId = sessionStorage.getItem("currentProjectId");
            } catch (e) { }
        }

        // 6. 임시 하드코딩 (개발용)
        if (!projectId) {
            projectId = "PRJ001"; // 개발용 임시 프로젝트 ID
            console.log("프로젝트 ID를 찾을 수 없어 임시 ID 사용:", projectId);
        }

        console.log("최종 프로젝트 ID:", projectId);
        return projectId;

    } catch (e) {
        console.error("프로젝트 ID 가져오기 실패:", e);
        return "PRJ001"; // 기본값
    }
};
